import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { ReporteTrimestral } from '../models/reporte-trimestral.model';
import { environment } from '../../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class ReporteTrimestralService {
  private readonly http = inject(HttpClient);
  private readonly apiUrl = `${environment.apiUrl}/reportes-trimestrales`;

  getReportes(): Observable<ReporteTrimestral[]> {
    return this.http.get<ReporteTrimestral[]>(this.apiUrl);
  }

  getReporte(id: number): Observable<ReporteTrimestral> {
    return this.http.get<ReporteTrimestral>(`${this.apiUrl}/${id}`);
  }

  crearReporte(data: Partial<ReporteTrimestral>): Observable<ReporteTrimestral> {
    return this.http.post<ReporteTrimestral>(this.apiUrl, data);
  }

  actualizarReporte(id: number, data: Partial<ReporteTrimestral>): Observable<ReporteTrimestral> {
    return this.http.put<ReporteTrimestral>(`${this.apiUrl}/${id}`, data);
  }

  eliminarReporte(id: number): Observable<void> {
    return this.http.delete<void>(`${this.apiUrl}/${id}`);
  }
}
